# Fix: la tarjeta "Por abrir" del dashboard de Franquicias salia en 0.
# Causa: api.js convierte las llaves a camelCase (por_abrir -> porAbrir) y el dashboard leia por_abrir.
# Correr desde la raiz del repo (fpt-contratos), luego git add -A ; git commit ; git push.

function Write-FileFromBase64 {
    param([string]$RelativePath, [string]$Base64Content)
    $fullPath = Join-Path (Get-Location) $RelativePath
    $dir = Split-Path $fullPath -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    [System.IO.File]::WriteAllBytes($fullPath, [System.Convert]::FromBase64String($Base64Content))
    Write-Host "Escrito: $RelativePath"
}

